import type { OwnedMap, SharedMap, Visibility } from "./scans";

/** One card in "Your maps" or "Community". */
export interface MapSummary {
  id: string;
  name: string;
  visibility: Visibility;
  /** Guest link. */
  sharePath: string;
  /** Set when someone else owns the map and shared it with you. */
  sharedBy?: string;
  /** Kind of place, matching the Explore chips planned in DESIGN.md. The API doesn't store it yet. */
  place?: "Campus" | "Event" | "Hospital" | "Trail" | "Building";
  /** ISO time of the last change, if known. */
  updated?: string;
  /** True for your own maps: the card offers rename, sharing and delete. */
  owned?: boolean;
}

export function fromOwned(map: OwnedMap): MapSummary {
  return {
    id: map.shareId,
    name: map.name,
    visibility: map.visibility,
    sharePath: map.sharePath,
    updated: map.updatedAt,
    owned: true,
  };
}

export function fromShared(map: SharedMap): MapSummary {
  return {
    id: map.shareId,
    name: map.name,
    visibility: map.visibility,
    sharePath: map.sharePath,
    updated: map.updatedAt,
    sharedBy: map.owner,
  };
}

export type MapFilter = "all" | "public" | "unlisted" | "private" | "shared";

export const MAP_FILTERS: { value: MapFilter; label: string }[] = [
  { value: "all", label: "All" },
  { value: "public", label: "Public" },
  { value: "unlisted", label: "Unlisted" },
  { value: "private", label: "Private" },
  { value: "shared", label: "Shared with me" },
];

/** Public/Unlisted/Private filter your own maps. "Shared with me" shows maps others own. */
export function filterMaps(maps: MapSummary[], filter: MapFilter): MapSummary[] {
  if (filter === "all") return maps;
  if (filter === "shared") return maps.filter((m) => m.sharedBy);
  return maps.filter((m) => !m.sharedBy && m.visibility === filter);
}

/**
 * Where a map was opened from, carried in the router's location state so the map
 * page can offer "← Community" or "← Your maps". Maps opened from a shared link or
 * QR code have none, and show the Path logo instead.
 */
export interface MapOrigin {
  from: string;
  fromLabel: string;
  mapName?: string;
}

export function readMapOrigin(state: unknown): MapOrigin | null {
  const value = state as Partial<MapOrigin> | null;
  return value && typeof value.from === "string" && typeof value.fromLabel === "string"
    ? { from: value.from, fromLabel: value.fromLabel, mapName: value.mapName }
    : null;
}

import { useEffect, useRef, type ReactNode } from "react";

/**
 * A modal "Are you sure?" built on <dialog>, which traps focus, closes on Escape and
 * returns focus to whatever opened it. The safe choice (Cancel) gets focus first.
 */
export default function ConfirmDialog({
  open,
  title,
  children,
  confirmLabel,
  busy = false,
  onConfirm,
  onCancel,
}: {
  open: boolean;
  title: string;
  children: ReactNode;
  confirmLabel: string;
  busy?: boolean;
  onConfirm: () => void;
  onCancel: () => void;
}) {
  const ref = useRef<HTMLDialogElement>(null);
  const cancelRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    const dialog = ref.current;
    if (!dialog) return;
    if (open && !dialog.open) {
      dialog.showModal();
      cancelRef.current?.focus();
    } else if (!open && dialog.open) {
      dialog.close();
    }
  }, [open]);

  return (
    <dialog
      ref={ref}
      data-surface="light"
      aria-labelledby="confirm-title"
      onCancel={(event) => {
        event.preventDefault();
        if (!busy) onCancel();
      }}
      className="m-auto w-[min(100%-2rem,26rem)] rounded-2xl bg-surface p-6 text-forest shadow-2xl backdrop:bg-night/60"
    >
      <h2 id="confirm-title" className="font-display text-2xl leading-tight font-black">
        {title}
      </h2>
      <div className="mt-3 space-y-2 leading-relaxed">{children}</div>
      <div className="mt-6 grid grid-cols-2 gap-3">
        <button
          ref={cancelRef}
          type="button"
          onClick={onCancel}
          disabled={busy}
          className="min-h-12 rounded-full font-bold text-forest ring-2 ring-forest"
        >
          Cancel
        </button>
        <button
          type="button"
          onClick={onConfirm}
          disabled={busy}
          className="min-h-12 rounded-full bg-rust px-4 font-bold text-paper disabled:opacity-70"
        >
          {busy ? "Deleting…" : confirmLabel}
        </button>
      </div>
    </dialog>
  );
}

